import{_ as t,C as e,o as s,c as r,j as i,E as l,a as n,a3 as d}from"./chunks/framework.C6R8kWFE.js";const p=JSON.parse(`{"title":"4-hafta","description":"","frontmatter":{"title":"4-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"11-sinf","link":"/11-sinf/"},"n":4,"bob":"I-bob · Dasturiy ta'minot ishlab chiqish asoslari","lessons":[{"g":10,"title":"Loyihalash andozalari: Observer va hodisalar arxitekturasi","lead":"Bitta voqea, ko'p javob beruvchi: Observer yordamida «buyurtma yakunlandi» signalini kuzatuvchilarga tarqatamiz va kod bir-biriga bog'lanib qolishining oldini olamiz.","link":"/11-sinf/hafta-04/dars-1","slide":"/slaydlar/11-sinf/hafta-04/dars-1.html","test":"/slaydlar/11-sinf/hafta-04/dars-1-test.html"},{"g":11,"title":"REST API va JSON asoslari: REST tamoyillari va HTTP","lead":"Har bir ilova serverdan ma'lumotni bir xil tilda so'raydi: HTTP. Bugun kutubxona uchun o'z REST API'ngizni yozib, curl bilan chaqirasiz.","link":"/11-sinf/hafta-04/dars-2","slide":"/slaydlar/11-sinf/hafta-04/dars-2.html","test":"/slaydlar/11-sinf/hafta-04/dars-2-test.html"},{"g":12,"title":"REST API va JSON asoslari: JSON formati, kontrakt va xavfsizlik","lead":"API ning yuragi: JSON kontrakti. Maydonlar nomi, xato formati va xavfsizlik qoidalari bo'yicha mijoz va server o'rtasida «kelishuv» tuzamiz.","link":"/11-sinf/hafta-04/dars-3","slide":"/slaydlar/11-sinf/hafta-04/dars-3.html","test":"/slaydlar/11-sinf/hafta-04/dars-3-test.html"}],"test":"/slaydlar/11-sinf/hafta-04/hafta-test.html"}},"headers":[],"relativePath":"11-sinf/hafta-04/index.md","filePath":"11-sinf/hafta-04/index.md"}`),c={name:"11-sinf/hafta-04/index.md"},u={class:"blk"},h={id:"uyga-vazifa",tabindex:"-1"};function v(f,a,b,m,g,y){const o=e("Icon");return s(),r("div",null,[i("div",u,[i("h2",h,[l(o,{name:"house"}),a[0]||(a[0]=n(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Har bir vazifa 20–30 daqiqa. Parol, shaxsiy token, maxfiy kalit va shaxsiy ma&#39;lumotlarni repozitoriyga yozmang: topshirishda faqat ochiq GitHub repo yoki Pull Request havolasi kerak.</p><h3 id="_10-dars-uchun-observer-va-eventbus" tabindex="-1">10-dars uchun (Observer va EventBus) <a class="header-anchor" href="#_10-dars-uchun-observer-va-eventbus" aria-label="Permalink to &quot;10-dars uchun (Observer va EventBus)&quot;">​</a></h3><p><strong>1-topshiriq: «Kutubxona EventBus tizimi»</strong></p><ol><li>O&#39;z GitHub portfolio repozitoriyangizda <code>feature/observer-eventbus</code> tarmog&#39;ini oching.</li><li><code>library_events.py</code> faylida markaziy <code>EventBus</code> sinfini e&#39;lon qiling (<code>subscribe</code>, <code>unsubscribe</code>, <code>publish</code>).</li><li><code>book:borrowed</code> hodisasi uchun ikkita kuzatuvchi yarating: <ul><li><code>AuditLogger</code> — berilgan kitob va o&#39;quvchi ma&#39;lumotlarini <code>logs/library.log</code> fayliga qo&#39;shadi;</li><li><code>StudentNotifier</code> — qaytarish muddatini hisoblab terminalga xabar chiqaradi.</li></ul></li><li><code>test_events.py</code> faylida <code>unittest.mock.MagicMock</code> yordamida <code>publish</code> chaqirilganda barcha kuzatuvchilar ishga tushishini tekshiruvchi 2 ta unit test yozing.</li><li>Semantik commitlar bilan GitHub&#39;ga yuboring.</li></ol><p><strong>Kutiladigan natija:</strong> bo&#39;sh bog&#39;langan, OCP talablariga mos, testlangan EventBus kodi.<br><strong>Topshirish:</strong> GitHub commit yoki fayl havolasi.</p><hr><h3 id="_11-dars-uchun-rest-tamoyillari-va-http-metodlari" tabindex="-1">11-dars uchun (REST tamoyillari va HTTP metodlari) <a class="header-anchor" href="#_11-dars-uchun-rest-tamoyillari-va-http-metodlari" aria-label="Permalink to &quot;11-dars uchun (REST tamoyillari va HTTP metodlari)&quot;">​</a></h3><p><strong>2-topshiriq: «REST API URI loyihasi va curl sinovlari»</strong></p><ol><li><code>docs/api_design.md</code> faylida «Kutubxona boshqaruvi» tizimi uchun RESTful endpointlar jadvalini tuzing: <ul><li>Kitoblarni olish (<code>GET /api/v1/books</code>), yangi kitob qo&#39;shish (<code>POST</code>), ID bo&#39;yicha olish (<code>GET /api/v1/books/{id}</code>), o&#39;chirish (<code>DELETE</code>);</li><li>Ko&#39;plik otlar, ierarxiya va to&#39;g&#39;ri HTTP metodlari qo&#39;llansin.</li></ul></li><li>Har bir amal uchun qaytishi kerak bo&#39;lgan kutilayotgan HTTP status kodlarini (200, 201, 204, 400, 404) yozing.</li><li><code>test_api.sh</code> nomli skript fayl tuzib, unga ushbu endpointlarni sinovdan o&#39;tkazuvchi kamida 4 ta <code>curl</code> buyrug&#39;ini yozing (<code>-X</code>, <code>-H &quot;Content-Type: application/json&quot;</code>, <code>-d</code>, <code>-v</code> bayroqlari bilan).</li></ol><p><strong>Kutiladigan natija:</strong> to&#39;g&#39;ri loyihalangan RESTful URI hujjati va terminalda ishlovchi curl sinov skripti.<br><strong>Topshirish:</strong> <code>docs/api_design.md</code> va <code>test_api.sh</code> havolasi.</p><hr><h3 id="_12-dars-uchun-json-formati-kontrakt-va-xavfsizlik" tabindex="-1">12-dars uchun (JSON formati, Kontrakt va Xavfsizlik) <a class="header-anchor" href="#_12-dars-uchun-json-formati-kontrakt-va-xavfsizlik" aria-label="Permalink to &quot;12-dars uchun (JSON formati, Kontrakt va Xavfsizlik)&quot;">​</a></h3><p><strong>3-topshiriq: «JSON Kontrakt, Error Envelope va DTO xavfsizligi»</strong></p><ol><li><code>contracts.py</code> faylida quyidagi qoidalarga mos keluvchi JSON serializatsiya funksiyalarini yozing: <ul><li>Yagona xatolik formati (<code>Error Envelope</code>): <code>{&quot;error&quot;: {&quot;code&quot;: &quot;...&quot;, &quot;message&quot;: &quot;...&quot;, &quot;details&quot;: [...]}}</code> qaytaruvchi <code>make_error_response()</code> funksiyasi;</li><li>Paginatsiya javobini shakllantiruvchi <code>make_paginated_response(data, limit, offset, total)</code> funksiyasi (<code>data</code> va <code>meta</code> bo&#39;limlari bilan);</li><li>Xavfsiz DTO filtri: Foydalanuvchi obyektidan <code>password_hash</code>, <code>token</code>, <code>secret_key</code> maydonlarini olib tashlab, sanalarni ISO-8601 UTC formatiga o&#39;tkazuvchi <code>sanitize_user()</code> funksiyasi.</li></ul></li><li><code>test_contracts.py</code> faylida har uchala funksiyani <code>pytest</code> yoki <code>assert</code> bilan tekshiruvchi testlar yozing.</li><li>Barcha ishlarni <code>main</code> tarmog&#39;iga Pull Request qilib yuboring.</li></ol><p><strong>Kutiladigan natija:</strong> xalqaro standartlarga mos, xavfsiz JSON kontrakt moduli va yashil unit testlar.<br><strong>Topshirish:</strong> GitHub Pull Request havolasi.</p><hr>',16))])])}const q=t(c,[["render",v]]);export{p as __pageData,q as default};
